package java_basics;

public class Met_square {
	
	public int square(int n) {
		int sq=n*n;
		return sq;
		
		
	}

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		Met_square obj=new Met_square();
			int a=obj.square(9);
				System.out.println("Square = "+a);
		

	}

}
